"""Shared post-processing utilities for Java test code generated by LLMs.

All functions are pure and stateless; they can be imported by any engine
adapter without pulling in adapter-specific state.
"""

from __future__ import annotations

from pathlib import Path
import re

_RE_PLACEHOLDER_OUTPUT = re.compile(r"^\s*<\|[^|>]+\|>\s*$")
_RE_JUNIT4_ANNOT = re.compile(r"^\s*@(Test|Before|After|BeforeClass|AfterClass)\b")


def strip_code_fences(code: str) -> str:
    """Remove markdown code fences that LLMs sometimes include despite instructions."""
    stripped = code.strip()
    if stripped.startswith("```"):
        first_newline = stripped.find("\n")
        if first_newline != -1:
            stripped = stripped[first_newline + 1:]
        if stripped.rstrip().endswith("```"):
            last_fence = stripped.rstrip().rfind("```")
            stripped = stripped[:last_fence].rstrip()
    return stripped


def has_balanced_java_delimiters(code: str) -> bool:
    """Return True when braces/parens/brackets are balanced (skips comments and strings)."""
    brace = paren = bracket = 0
    idx = 0
    n = len(code)
    in_string: str | None = None

    while idx < n:
        ch = code[idx]
        if in_string:
            if ch == "\\" and idx + 1 < n:
                idx += 2
                continue
            if ch == in_string:
                in_string = None
            idx += 1
            continue

        if ch in {'"', "'"}:
            in_string = ch
            idx += 1
            continue

        if ch == "/" and idx + 1 < n and code[idx + 1] == "/":
            idx = code.find("\n", idx)
            if idx == -1:
                break
            idx += 1
            continue

        if ch == "/" and idx + 1 < n and code[idx + 1] == "*":
            end_comment = code.find("*/", idx + 2)
            if end_comment == -1:
                return False
            idx = end_comment + 2
            continue

        if ch == "{":
            brace += 1
        elif ch == "}":
            brace -= 1
            if brace < 0:
                return False
        elif ch == "(":
            paren += 1
        elif ch == ")":
            paren -= 1
            if paren < 0:
                return False
        elif ch == "[":
            bracket += 1
        elif ch == "]":
            bracket -= 1
            if bracket < 0:
                return False
        idx += 1

    return brace == 0 and paren == 0 and bracket == 0 and in_string is None


def is_valid_generated_test(code: str) -> bool:
    """Return True when *code* looks like a well-formed Java test class."""
    stripped = code.strip()
    if not stripped:
        return False
    if _RE_PLACEHOLDER_OUTPUT.match(stripped):
        return False
    if "class " not in stripped:
        return False
    if "{" not in stripped or "}" not in stripped:
        return False
    return has_balanced_java_delimiters(stripped)


def dedupe_import_lines(code: str) -> str:
    """Remove duplicate Java import lines while preserving original order."""
    seen: set[str] = set()
    out: list[str] = []
    for line in code.splitlines():
        if re.match(r"^\s*import\s+.+;\s*$", line):
            norm = line.strip()
            if norm in seen:
                continue
            seen.add(norm)
        out.append(line)
    return "\n".join(out) + ("\n" if code.endswith("\n") else "")


def strip_conflicting_junit_constructs(code: str, junit_family: str) -> str:
    """Drop obvious JUnit4/JUnit5 cross-contamination that causes compile errors.

    JUnit4 mode: removes jupiter imports and MockitoExtension annotations.
    JUnit5 mode: removes JUnit4 imports and MockitoJUnitRunner annotations.
    """
    fam = (junit_family or "").lower().strip()
    out: list[str] = []
    for line in code.splitlines():
        s = line.strip()
        if fam == "junit4":
            if s.startswith("import org.junit.jupiter."):
                continue
            if s.startswith("import org.mockito.junit.jupiter."):
                continue
            if "@ExtendWith(" in s or "MockitoExtension" in s:
                continue
        elif fam == "junit5":
            if s.startswith("import org.junit.") and not s.startswith("import org.junit.jupiter."):
                continue
            if s.startswith("import org.mockito.junit.MockitoJUnitRunner"):
                continue
            if "@RunWith(" in s or "MockitoJUnitRunner" in s:
                continue
        out.append(line)
    return "\n".join(out) + ("\n" if code.endswith("\n") else "")


def promote_junit4_test_methods_to_public(code: str, junit_family: str) -> str:
    """Ensure JUnit 4 @Test/@Before/@After methods are public.

    Surefire fails at init time with "method should be public" when these
    are package-private.  Only rewrites methods directly following the
    standard JUnit 4 lifecycle annotations.
    """
    if (junit_family or "").lower().strip() != "junit4":
        return code

    lines = code.splitlines()
    out: list[str] = []
    pending_public = False
    for line in lines:
        stripped = line.strip()
        if _RE_JUNIT4_ANNOT.match(stripped):
            pending_public = True
            out.append(line)
            continue
        if pending_public:
            if (
                "(" in stripped
                and ")" in stripped
                and "{" in stripped
                and not re.search(r"\b(public|protected|private)\b", stripped)
            ):
                indent = line[: len(line) - len(line.lstrip())]
                line = f"{indent}public {stripped}"
            pending_public = False
        if stripped and not stripped.startswith("@"):
            pending_public = False
        out.append(line)

    return "\n".join(out) + ("\n" if code.endswith("\n") else "")


def normalize_generated_test(code: str, junit_family: str) -> str:
    """Apply the full post-processing pipeline to LLM-generated Java test code.

    Steps (in order):
    1. Strip markdown code fences
    2. Deduplicate import lines
    3. Remove cross-JUnit-family constructs
    4. Promote JUnit 4 test methods to public

    Returns the normalized code string.
    """
    code = strip_code_fences(code)
    code = dedupe_import_lines(code)
    code = strip_conflicting_junit_constructs(code, junit_family)
    code = promote_junit4_test_methods_to_public(code, junit_family)
    return code


def strip_java_comments_and_strings(code: str) -> str:
    """Return Java-like code with comments and string literals blanked out."""
    out: list[str] = []
    idx = 0
    n = len(code or "")
    while idx < n:
        ch = code[idx]
        if ch == "/" and idx + 1 < n and code[idx + 1] == "/":
            newline = code.find("\n", idx)
            if newline == -1:
                break
            out.append("\n")
            idx = newline + 1
            continue
        if ch == "/" and idx + 1 < n and code[idx + 1] == "*":
            end = code.find("*/", idx + 2)
            if end == -1:
                break
            out.append("\n" * code[idx:end + 2].count("\n"))
            idx = end + 2
            continue
        if ch in {'"', "'"}:
            quote = ch
            out.append('""' if quote == '"' else "''")
            idx += 1
            while idx < n:
                if code[idx] == "\\":
                    idx += 2
                    continue
                if code[idx] == quote:
                    idx += 1
                    break
                if code[idx] == "\n":
                    out.append("\n")
                idx += 1
            continue
        out.append(ch)
        idx += 1
    return "".join(out)


def test_code_calls_any_method(test_code: str, method_names: list[str]) -> bool:
    """Return true when a Java test body syntactically invokes a method name."""
    if not test_code or not method_names:
        return False
    cleaned = strip_java_comments_and_strings(test_code)
    for raw_line in cleaned.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if re.search(r"\b(?:public|protected|private)\b[^;{=]*\([^)]*\)\s*(?:throws\b[^{}]*)?\{?\s*$", line):
            continue
        for method_name in method_names:
            if not method_name:
                continue
            escaped = re.escape(method_name)
            if re.search(rf"(?:\.|::)\s*{escaped}\s*\(", line) or re.search(rf"(?<![\w$]){escaped}\s*\(", line):
                return True
    return False


def is_valid_class_structure(content: str) -> bool:
    """Best-effort validation that content is one complete Java top-level type."""
    if not content:
        return False
    class_match = re.search(r"\b(?:class|interface|enum|record)\s+\w+[^\{]*\{", content)
    if not class_match:
        return False
    open_brace = content.find("{", class_match.start())
    if open_brace == -1:
        return False
    close_brace = _find_matching_java_brace(content, open_brace)
    return close_brace != -1 and not content[close_brace + 1:].strip()


def merge_test_patch_into_file(existing_content: str, patch: str) -> str:
    """Merge Java imports and test/lifecycle method snippets into a test class."""
    if not patch.strip():
        return existing_content
    if not existing_content.strip():
        return patch
    if not is_valid_class_structure(existing_content):
        return existing_content

    imports = _java_import_lines(existing_content) + _java_import_lines(patch)
    static_imports = sorted({line for line in imports if line.strip().startswith("import static ")})
    normal_imports = sorted({line for line in imports if not line.strip().startswith("import static ")})
    body = _extract_java_class_body(patch) if _looks_like_full_java_source(patch) else patch
    method_blocks = _junit_or_lifecycle_method_blocks(body)
    methods_text = "\n\n".join(block.strip() for block in method_blocks if block.strip())
    if not methods_text.strip():
        cleaned_lines = []
        for line in patch.splitlines():
            stripped = line.strip()
            if stripped.startswith("package ") or stripped.startswith("import "):
                continue
            if re.search(r"\b(?:class|interface|enum|record)\s+", stripped):
                continue
            cleaned_lines.append(line)
        methods_text = "\n".join(cleaned_lines).strip()
    if not methods_text:
        return existing_content

    merged = _rewrite_java_imports(existing_content, normal_imports, static_imports)
    last_brace = merged.rfind("}")
    if last_brace == -1:
        return existing_content
    candidate = merged[:last_brace].rstrip() + "\n\n" + methods_text + "\n" + merged[last_brace:]
    return candidate if is_valid_class_structure(candidate) else existing_content


def render_callback_signature_grounding_section(project_root: Path, source_code: str) -> str:
    """Render exact callback/interface signatures mentioned by a source file."""
    imports: dict[str, str] = {}
    for match in re.finditer(r"(?m)^\s*import\s+([\w.]+)\s*;", source_code or ""):
        fqn = match.group(1)
        imports[fqn.rsplit(".", 1)[-1]] = fqn
    cleaned = strip_java_comments_and_strings(source_code or "")
    invoked_receivers = {
        match.group(1)
        for match in re.finditer(
            r"\b([A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*"
            r"[A-Za-z_$][A-Za-z0-9_$]*\s*\(",
            cleaned,
        )
        if match.group(1) not in {"this", "super"}
    }
    candidate_names: set[str] = set()
    declaration_re = re.compile(
        r"\b(?P<type>[A-Z][A-Za-z0-9_$.]*"
        r"(?:\s*<[^;(){}]+>)?(?:\[\])?)\s+"
        r"(?P<name>[a-z_$][A-Za-z0-9_$]*)\s*(?=[=;,)])"
    )
    for match in declaration_re.finditer(cleaned):
        if match.group("name") not in invoked_receivers:
            continue
        raw_type = (
            re.sub(r"<.*>", "", match.group("type"))
            .replace("[]", "")
            .strip()
        )
        simple_type = raw_type.rsplit(".", 1)[-1]
        if simple_type:
            candidate_names.add(simple_type)
    if not candidate_names:
        return ""

    def candidate_files(simple_name: str) -> list[Path]:
        files: list[Path] = []
        fqn = imports.get(simple_name)
        if fqn:
            rel = Path(*fqn.split(".")).with_suffix(".java")
            for base in (project_root / "src/main/java", project_root / "src/test/java"):
                path = base / rel
                if path.exists():
                    files.append(path)
        if not files:
            try:
                files.extend(list(project_root.rglob(f"{simple_name}.java"))[:3])
            except OSError:
                pass
        return files

    method_re = re.compile(
        r"(?m)^[ \t]*"
        r"(?:@[A-Za-z_$][A-Za-z0-9_$.]*(?:\([^)\r\n]*\))?[ \t\r\n]*)*"
        r"(?:(?:public|protected|default|static|final|synchronized|native|"
        r"abstract|strictfp)[ \t]+)*"
        r"(?:<[^;{}()\r\n]+>[ \t]+)?"
        r"(?!return\b|throw\b|new\b|if\b|for\b|while\b|switch\b|catch\b)"
        r"(?P<return>[A-Za-z_$][A-Za-z0-9_$.\[\]?]*"
        r"(?:[ \t]*<[^;{}()]+>)?(?:[ \t]*\[\])?)[ \t]+"
        r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)[ \t\r\n]*"
        r"\((?P<params>[^;{}]*)\)[ \t\r\n]*"
        r"(?:throws[ \t\r\n]+[^;{}]+)?[ \t\r\n]*(?:\{|;)"
    )
    signature_lines: list[str] = []
    for simple_name in sorted(candidate_names):
        for path in candidate_files(simple_name):
            try:
                text = path.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            declaration_text = strip_java_comments_and_strings(text)
            type_declaration = re.search(
                rf"\b(?P<abstract>abstract\s+)?"
                rf"(?P<kind>class|interface)\s+{re.escape(simple_name)}\b",
                declaration_text,
            )
            if not (
                type_declaration
                and (
                    type_declaration.group("kind") == "interface"
                    or type_declaration.group("abstract")
                )
            ):
                continue
            signatures: list[str] = []
            for match in method_re.finditer(declaration_text):
                if match.group("name") == simple_name:
                    continue
                signature = " ".join(match.group(0).strip().rstrip("{").rstrip(";").split())
                if signature not in signatures:
                    signatures.append(signature)
                if len(signatures) >= 16:
                    break
            if signatures:
                try:
                    label = path.relative_to(project_root)
                except ValueError:
                    label = path
                signature_lines.append(f"- {simple_name} ({label}):")
                signature_lines.extend(f"  * {sig}" for sig in signatures)
                break
        if len(signature_lines) >= 60:
            break
    if not signature_lines:
        return ""
    return "\n".join([
        "[Callback/Interface Signature Grounding]",
        "When creating anonymous classes, lambdas, filters, listeners, handlers, visitors, or predicates, use only these exact callback method signatures. Do not invent @Override method names or parameter lists.",
        "Prefer existing default/no-op implementations from the project when they are available and only override the one exact callback needed for the scenario.",
        "For assertions on base/interface variables, call only methods declared on that static type; if a subtype API is needed, first assert/cast to the concrete subtype.",
        *signature_lines,
    ])


def render_testing_stack_constraints(request) -> str:
    """Render Java/JUnit compatibility constraints from a GenerationRequest-like object."""
    lines: list[str] = []
    if getattr(request, "java_version", ""):
        lines.append(f"- Keep syntax compatible with Java {request.java_version}.")
    family = (getattr(request, "junit_family", "") or "").lower()
    if family == "junit4":
        lines.append("- Use JUnit 4 style only: org.junit.Test and org.junit.Assert.*.")
        lines.append("- Do not use org.junit.jupiter.* APIs.")
    elif family == "junit5":
        lines.append("- Use JUnit 5 style only: org.junit.jupiter.api.Test and org.junit.jupiter.api.Assertions.*.")
        lines.append("- Do not use org.junit.Test or org.junit.Assert.*.")
    elif getattr(request, "junit_version", ""):
        lines.append(f"- Use a JUnit API compatible with version {request.junit_version}.")
    if getattr(request, "junit_version", ""):
        lines.append(f"- Target JUnit version: {request.junit_version}.")
    return "\n".join(lines)


def _looks_like_full_java_source(code: str) -> bool:
    return bool(re.search(r"(?m)^\s*package\s+", code or "") or re.search(r"\b(?:class|interface|enum|record)\s+", code or ""))


def _java_import_lines(code: str) -> list[str]:
    return [line.strip() for line in (code or "").splitlines() if re.match(r"^\s*import\s+.+;\s*$", line)]


def _rewrite_java_imports(content: str, normal_imports: list[str], static_imports: list[str]) -> str:
    lines = [line for line in content.splitlines() if not re.match(r"^\s*import\s+.+;\s*$", line)]
    insert_at = 0
    for idx, line in enumerate(lines):
        if line.strip().startswith("package "):
            insert_at = idx + 1
            break
    import_block = normal_imports + static_imports
    if not import_block:
        return "\n".join(lines) + ("\n" if content.endswith("\n") else "")
    return "\n".join(lines[:insert_at] + [""] + import_block + [""] + lines[insert_at:]).strip() + "\n"


def _find_matching_java_brace(text: str, open_pos: int) -> int:
    depth = 0
    idx = open_pos
    n = len(text or "")
    while idx < n:
        ch = text[idx]
        if ch == "/" and idx + 1 < n and text[idx + 1] == "/":
            newline = text.find("\n", idx)
            if newline == -1:
                return -1
            idx = newline + 1
            continue
        if ch == "/" and idx + 1 < n and text[idx + 1] == "*":
            end = text.find("*/", idx + 2)
            if end == -1:
                return -1
            idx = end + 2
            continue
        if ch in {'"', "'"}:
            quote = ch
            idx += 1
            while idx < n:
                if text[idx] == "\\":
                    idx += 2
                    continue
                if text[idx] == quote:
                    idx += 1
                    break
                idx += 1
            continue
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return idx
        idx += 1
    return -1


def _extract_java_class_body(code: str) -> str:
    class_match = re.search(r"\b(?:class|interface|enum|record)\s+\w+[^\{]*\{", code or "")
    if not class_match:
        return code
    open_brace = code.find("{", class_match.start())
    close_brace = _find_matching_java_brace(code, open_brace)
    if open_brace == -1 or close_brace == -1:
        return code[class_match.end():]
    return code[open_brace + 1:close_brace]


def _junit_or_lifecycle_method_blocks(code: str) -> list[str]:
    def _brace_depth_before(position: int) -> int:
        """Return Java brace depth before ``position``, ignoring literals/comments."""
        depth = 0
        idx = 0
        text = code or ""
        limit = min(max(0, position), len(text))
        while idx < limit:
            ch = text[idx]
            if ch == "/" and idx + 1 < limit and text[idx + 1] == "/":
                newline = text.find("\n", idx + 2, limit)
                if newline == -1:
                    break
                idx = newline + 1
                continue
            if ch == "/" and idx + 1 < limit and text[idx + 1] == "*":
                end = text.find("*/", idx + 2, limit)
                if end == -1:
                    break
                idx = end + 2
                continue
            if ch in {'"', "'"}:
                quote = ch
                idx += 1
                while idx < limit:
                    if text[idx] == "\\":
                        idx += 2
                        continue
                    if text[idx] == quote:
                        idx += 1
                        break
                    idx += 1
                continue
            if ch == "{":
                depth += 1
            elif ch == "}":
                depth = max(0, depth - 1)
            idx += 1
        return depth

    blocks: list[str] = []
    pattern = re.compile(
        r"(?m)^\s*(?:@[\w.]+(?:\([^\n]*\))?\s*)*"
        r"(?:public|protected|private)?\s*(?:static\s+)?(?:final\s+)?"
        r"[\w.$<>\[\], ?]+\s+[A-Za-z_$][\w$]*\s*\([^;{}]*\)"
        r"(?:\s+throws\s+[^{};]+)?\s*\{"
    )
    for match in pattern.finditer(code or ""):
        # ``code`` is normally the body of the destination test class. Only
        # top-level members are promotable. Without this gate a try-with-
        # resources block inside an @Test method can match the broad Java
        # signature regex because ``try (Type name = ...) {`` resembles a
        # method header. Merging that false second block produces balanced but
        # uncompilable Java ("illegal start of type").
        if _brace_depth_before(match.start()) != 0:
            continue
        prefix = code[max(0, match.start() - 120):match.start()]
        header = code[match.start():match.end()]
        context = prefix + header
        if not any(token in context for token in ("@Test", "@Before", "@BeforeEach", "@After", "@AfterEach")):
            continue
        open_brace = code.find("{", match.end() - 1)
        close_brace = _find_matching_java_brace(code, open_brace)
        if close_brace != -1:
            blocks.append(code[match.start():close_brace + 1].strip())
    return blocks
